package org.batfish.vendor.rtx.representation;

import com.google.common.collect.Range;
import com.google.common.collect.RangeSet;
import com.google.common.collect.TreeRangeSet;
import java.io.Serializable;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import org.batfish.datamodel.IntegerSpace;
import org.batfish.datamodel.Ip;
import org.batfish.datamodel.IpSpace;

/**
 * A NAT descriptor: the bundle of settings that {@code nat descriptor <sub-command> <n> ...}
 * defines and that {@code ip <if> nat descriptor <n>} applies to an interface.
 */
public final class RtxNatDescriptor implements Serializable {

  /** Translation mode, from {@code nat descriptor type}. */
  public enum Type {
    /** No translation. The device's default. */
    NONE,
    /** Dynamic one-to-one address translation from the outer pool, plus static entries. */
    NAT,
    /** IP masquerade (NAPT), plus static entries. */
    MASQUERADE,
    /** Dynamic NAT first, falling back to masquerade once the outer pool is used up. */
    NAT_MASQUERADE
  }

  /** Outer addresses that the router learns at runtime instead of from the configuration. */
  public enum OuterAddressMnemonic {
    /** Address given by the peer over PPP IPCP. */
    IPCP,
    /** The interface's own primary address. */
    PRIMARY,
    /** The interface's secondary address. */
    SECONDARY,
    /** Address generated by MAP-E. */
    MAP_E,
    /** Address obtained by the IPv6 migration provisioning method. */
    HB46PP
  }

  /**
   * Ports masquerade uses when {@code nat descriptor masquerade port range} is not configured, per
   * the command reference for Rev.14.01 and later.
   */
  public static final IntegerSpace DEFAULT_MASQUERADE_PORTS =
      IntegerSpace.builder()
          .including(Range.closed(60000, 64095))
          .including(Range.closed(49152, 59999))
          .including(Range.closed(44096, 49151))
          .build();

  private final int _number;
  private @Nonnull Type _type;
  private final @Nonnull RangeSet<Ip> _outerAddresses;
  private @Nullable Ip _firstOuterAddress;
  private @Nullable OuterAddressMnemonic _outerMnemonic;
  private @Nullable IpSpace _innerAddresses;
  private @Nullable IntegerSpace _masqueradePorts;

  public RtxNatDescriptor(int number) {
    _number = number;
    // The device's default is `none`, i.e. a descriptor that exists but translates nothing.
    _type = Type.NONE;
    _outerAddresses = TreeRangeSet.create();
  }

  public int getNumber() {
    return _number;
  }

  public @Nonnull Type getType() {
    return _type;
  }

  public void setType(Type type) {
    _type = type;
  }

  /** The outer address pool, used by dynamic NAT. Empty if none was configured. */
  public @Nonnull RangeSet<Ip> getOuterAddresses() {
    return _outerAddresses;
  }

  /**
   * The first outer address that was configured. Masquerade uses only this one, regardless of how
   * large the pool is.
   */
  public @Nullable Ip getFirstOuterAddress() {
    return _firstOuterAddress;
  }

  public void setFirstOuterAddress(Ip firstOuterAddress) {
    _firstOuterAddress = firstOuterAddress;
  }

  /** Set when the outer address is a runtime-learned mnemonic rather than a literal range. */
  public @Nullable OuterAddressMnemonic getOuterMnemonic() {
    return _outerMnemonic;
  }

  public void setOuterMnemonic(OuterAddressMnemonic outerMnemonic) {
    _outerMnemonic = outerMnemonic;
  }

  /**
   * The inner addresses eligible for translation, or {@code null} for {@code auto}, which is the
   * default and means all of them.
   */
  public @Nullable IpSpace getInnerAddresses() {
    return _innerAddresses;
  }

  public void setInnerAddresses(IpSpace innerAddresses) {
    _innerAddresses = innerAddresses;
  }

  /** The configured masquerade port ranges, or {@code null} to use {@link #getMasqueradePorts}. */
  public @Nullable IntegerSpace getConfiguredMasqueradePorts() {
    return _masqueradePorts;
  }

  public void setMasqueradePorts(IntegerSpace masqueradePorts) {
    _masqueradePorts = masqueradePorts;
  }

  /** The ports masquerade may assign, falling back to the device's defaults. */
  public @Nonnull IntegerSpace getMasqueradePorts() {
    return _masqueradePorts == null ? DEFAULT_MASQUERADE_PORTS : _masqueradePorts;
  }
}
